// PreviewIframe — thin <iframe> wrapper.
//
// The iframe runs the user's generated artifact via `srcdoc`, so it shares
// the parent origin (`allow-same-origin`). We accept the security trade-off:
// the artifact is generated by the user's chat with our LLM, not third-party
// code, and the parent origin holds no secrets the artifact could exfiltrate.

import { forwardRef, useEffect, useRef } from 'react';
import styled from 'styled-components';

const Frame = styled.iframe`
  width: 100%;
  height: 100%;
  border: 0;
  background: ${(p) => p.theme.colors.bg100};
  display: block;
`;

export interface PreviewIframeProps {
  srcdoc: string;
  title?: string;
  onLoad?: () => void;
  onMessageReady?: (iframe: HTMLIFrameElement) => void;
}

const DEFAULT_SANDBOX =
  'allow-scripts allow-forms allow-popups allow-modals allow-downloads allow-same-origin';

/**
 * Mounts a preview iframe with the given srcdoc. Forwarded ref points to the
 * underlying `<iframe>` so the caller can build an `IframeBridge` against it.
 */
export const PreviewIframe = forwardRef<HTMLIFrameElement, PreviewIframeProps>(
  function PreviewIframe({ srcdoc, title = 'Preview', onLoad, onMessageReady }, ref) {
    const localRef = useRef<HTMLIFrameElement | null>(null);

    // Notify caller once the iframe is mounted (so they can wire up the
    // bridge before the artifact's overlay sends OVERLAY_READY).
    useEffect(() => {
      if (!localRef.current) return;
      onMessageReady?.(localRef.current);
    }, [onMessageReady]);

    return (
      <Frame
        ref={(el) => {
          localRef.current = el;
          if (typeof ref === 'function') ref(el);
          else if (ref) ref.current = el;
        }}
        title={title}
        data-testid="preview-iframe"
        sandbox={DEFAULT_SANDBOX}
        srcDoc={srcdoc}
        onLoad={onLoad}
      />
    );
  },
);
